INSERT INTO zozo_import(payload) VALUES ('{"product_id":"07b22a6c-a8bc-4a6a-a92d-416b87a24150","source_url":"https://zozo.jp/shop/minius/goods/99755838/?did=160972152","name":"\u3010URBAN ISLAND SOCIETY/\u30A2\u30FC\u30D0\u30F3\u30A2\u30A4\u30E9\u30F3\u30C9\u30BD\u30B5\u30A8\u30C6\u30A3\u3011UIS MAITAI HOODIE/\u30D1\u30FC\u30AB\u30FC \u30D7\u30EB\u30AA\u30FC\u30D0\u30FC \u30B9\u30A6\u30A7\u30C3\u30C8 \u30CF\u30EF\u30A4\u30A2\u30F3 \u30C8\u30ED\u30D4\u30AB\u30EB \u30B0\u30E9\u30D5\u30A3\u30C3\u30AF","brand":"URBAN ISLAND SOCIETY","description":"\u30C8\u30ED\u30D4\u30AB\u30EB\u306A\u30A2\u30FC\u30C8\u30EF\u30FC\u30AF\u304C\u969B\u7ACB\u3064\u3001\u30CF\u30EF\u30A4\u30A2\u30F3\u30B9\u30A6\u30A7\u30C3\u30C8\u30D1\u30FC\u30AB\u30FC\u30AB\u30E9\u30D5\u30EB\u306A\u30C8\u30ED\u30D4\u30AB\u30EB\u30B0\u30E9\u30D5\u30A3\u30C3\u30AF\u304C\u5370\u8C61\u7684\u306A\u30D7\u30EB\u30AA\u30FC\u30D0\u30FC\u30D1\u30FC\u30AB\u30FC\u304C\u767B\u5834\u3002\u30DE\u30A4\u30BF\u30A4\uFF08\u30C8\u30ED\u30D4\u30AB\u30EB\u30AB\u30AF\u30C6\u30EB\uFF09\u3092\u30E2\u30C1\u30FC\u30D5\u306B\u3057\u305F\u5927\u80C6\u306A\u30D0\u30C3\u30AF\u30D7\u30EA\u30F3\u30C8\u304C\u7279\u5FB4\u7684\u306A\u3001\u904A\u3073\u5FC3\u6E80\u8F09\u306E\u30B9\u30A6\u30A7\u30C3\u30C8\u30A2\u30A4\u30C6\u30E0\u3067\u3059\u3002\u80F8\u5143\u306E\u30B0\u30E9\u30C7\u30FC\u30B7\u30E7\u30F3\u30ED\u30B4\u523A\u7E4D\u3068\u3001\u80CC\u4E2D\u4E00\u9762\u306B\u5E83\u304C\u308B\u30AB\u30E9\u30D5\u30EB\u306A\u30A2\u30FC\u30C8\u30EF\u30FC\u30AF\u304C\u7D76\u5999\u306A\u30D0\u30E9\u30F3\u30B9\u3002\u79CB\u51AC\u30B7\u30FC\u30BA\u30F3\u306B\u6696\u304B\u304F\u3001\u500B\u6027\u3092\u4E3B\u5F35\u3067\u304D\u308B\u4E00\u679A\u3067\u3059\u3002\uD83C\uDFAF \u5546\u54C1\u306E\u7279\u5FB4\u30A4\u30F3\u30D1\u30AF\u30C8\u629C\u7FA4\u306E\u30B0\u30E9\u30D5\u30A3\u30C3\u30AF\u30C7\u30B6\u30A4\u30F3\u30FB\u30C8\u30ED\u30D4\u30AB\u30EB\u30D0\u30C3\u30AF\u30D7\u30EA\u30F3\u30C8 - \u30DE\u30A4\u30BF\u30A4\u30AB\u30AF\u30C6\u30EB\u3092\u30E2\u30C1\u30FC\u30D5\u306B\u3057\u305F\u5927\u80C6\u306A\u30A2\u30FC\u30C8\u30EF\u30FC\u30AF\u30FBHAWAII\u30ED\u30B4 - \u30EC\u30C8\u30ED\u306A\u30D5\u30A9\u30F3\u30C8\u3067\u30CF\u30EF\u30A4\u30A2\u30F3\u30E0\u30FC\u30C9\u3092\u6F14\u51FA\u30FBURBAN ISLAND SOCIETY\u30C6\u30AD\u30B9\u30C8 - \u30D6\u30E9\u30F3\u30C9\u30A2\u30A4\u30C7\u30F3\u30C6\u30A3\u30C6\u30A3\u3092\u8868\u73FE\u30FB\u30DE\u30EB\u30C1\u30AB\u30E9\u30FC\u30B0\u30E9\u30D5\u30A3\u30C3\u30AF - \u30A4\u30A8\u30ED\u30FC\u3001\u30D4\u30F3\u30AF\u3001\u30D6\u30EB\u30FC\u3001\u30B0\u30EA\u30FC\u30F3\u306E\u9BAE\u3084\u304B\u306A\u914D\u8272\u30FB\u30B9\u30C8\u30EA\u30FC\u30C8\u30A2\u30FC\u30C8\u611F - 90\u5E74\u4EE3\u30C6\u30A4\u30B9\u30C8\u306E\u30CE\u30B9\u30BF\u30EB\u30B8\u30C3\u30AF\u306A\u30C7\u30B6\u30A4\u30F3 \u5B9A\u756A\u30D7\u30EB\u30AA\u30FC\u30D0\u30FC\u30D1\u30FC\u30AB\u30FC\u306E\u30C7\u30A3\u30C6\u30FC\u30EB\u30FB\u30D5\u30FC\u30C9\u4ED8\u304D\u30C7\u30B6\u30A4\u30F3 - \u5C0F\u9854\u52B9\u679C\u3082\u671F\u5F85\u3067\u304D\u308B\u6DF1\u3081\u306E\u30D5\u30FC\u30C9\u30FB\u30C9\u30ED\u30FC\u30B3\u30FC\u30C9 - \u30D5\u30FC\u30C9\u306E\u8ABF\u7BC0\u304C\u53EF\u80FD\u30FB\u30AB\u30F3\u30AC\u30EB\u30FC\u30DD\u30B1\u30C3\u30C8 - \u5B9F\u7528\u7684\u306A\u5927\u304D\u3081\u30DD\u30B1\u30C3\u30C8\u30FB\u30EA\u30D6\u30CB\u30C3\u30C8\u4ED5\u69D8 - \u8896\u53E3\u3068\u88FE\u306E\u30EA\u30D6\u3067\u30D5\u30A3\u30C3\u30C8\u611F\u8ABF\u6574\u30FB\u30AA\u30FC\u30D0\u30FC\u30B5\u30A4\u30BA\u30D5\u30A3\u30C3\u30C8 - \u3086\u3063\u305F\u308A\u7740\u3089\u308C\u308B\u30EA\u30E9\u30C3\u30AF\u30B9\u30B7\u30EB\u30A8\u30C3\u30C8 \u79CB\u51AC\u306B\u5B09\u3057\u3044\u6696\u304B\u3055\u30FB\u88CF\u8D77\u6BDB\u4ED5\u69D8 - \u3075\u3093\u308F\u308A\u67D4\u3089\u304B\u306A\u808C\u89E6\u308A\u30FB\u4FDD\u6E29\u6027\u25CE - \u8D77\u6BDB\u7D20\u6750\u3067\u6696\u304B\u3055\u3092\u30AD\u30FC\u30D7\u30FB\u9069\u5EA6\u306A\u539A\u307F - \u771F\u51AC\u306E\u30E1\u30A4\u30F3\u30A2\u30A6\u30BF\u30FC\u3068\u3057\u3066\u6D3B\u8E8D\u30FB\u901A\u